1	/**
2	 * Decides whether a plain-text message body keeps the monospace face.
3	 *
4	 * Prose reads in the proportional UI face. Hard-wrapped text that depends on
5	 * column alignment (quoted replies, indented blocks, code, ASCII tables) loses
6	 * its meaning there, so it falls back to the raw monospace rendering. The test
7	 * is deterministic and looks only at line shapes; the body is never rewritten.
8	 */
9	export function bodyNeedsMonospace(bodyText: string): boolean {
10	  const lines = bodyText.split('\n');
11	  let indentedRun = 0;
12	  let pipeLines = 0;
13	  for (const line of lines) {
14	    // Quoted reply line: optional indent, then ">".
15	    if (/^ {0,3}>/.test(line)) return true;
16	    // Two consecutive lines with 4+ leading spaces (or a tab): code, tables, signatures.
17	    if (/^(?: {4,}|\t)\S/.test(line)) {
18	      indentedRun += 1;
19	      if (indentedRun >= 2) return true;
20	    } else {
21	      indentedRun = 0;
22	    }
23	    // Table-ish: two or more lines with at least two pipes.
24	    if ((line.match(/\|/g)?.length ?? 0) >= 2) {
25	      pipeLines += 1;
26	      if (pipeLines >= 2) return true;
27	    }
28	  }
29	  return false;
30	}
31	
32	export interface MessageBodyParts {
33	  /** The prose part. Equals the whole body when nothing is split off. */
34	  main: string;
35	  /** From an RFC 3676 `-- ` delimiter line to the trailing quote or the end. */
36	  signature: string | null;
37	  /** The trailing quoted block, from its attribution line (if any) to the end. */
38	  quoted: string | null;
39	}
40	
41	const QUOTE_LINE = /^ {0,3}>/;
42	const ATTRIBUTION = /^On .+ wrote:$/i;
43	const ORIGINAL_MESSAGE = /^-{2,}\s*Original Message\s*-{2,}$/i;
44	const SIGNATURE_DELIMITER = /^-- ?$/;
45	const MAX_SIGNATURE_LINES = 12;
46	
47	/**
48	 * Splits a plain-text body into prose, an optional signature and an optional
49	 * trailing quote. Deterministic and lossless: the parts are contiguous slices,
50	 * so `main + (signature ?? '') + (quoted ?? '')` is always the exact original
51	 * text, line breaks included. Nothing is rewritten, and `>` characters stay.
52	 *
53	 * - Trailing quote: an attribution ("On … wrote:", which may wrap onto two
54	 *   lines, or "-----Original Message-----") followed by blank lines and a
55	 *   contiguous run of `>` lines that reaches the end of the body, or a bare run
56	 *   of at least two `>` lines that reaches the end. Quotes in the middle of a
57	 *   body are never split off.
58	 * - Signature: the last line that is exactly `-- ` or `--`, only when at most 12
59	 *   lines follow it before the quote or the end of the body.
60	 * - A body that would be left with no prose (all quote) is returned unsplit.
61	 */
62	export function splitMessageBody(bodyText: string): MessageBodyParts {
63	  const whole: MessageBodyParts = { main: bodyText, signature: null, quoted: null };
64	  const lines = bodyText.split('\n');
65	  const starts: number[] = [];
66	  let offset = 0;
67	  for (const line of lines) {
68	    starts.push(offset);
69	    offset += line.length + 1;
70	  }
71	  const text = (index: number): string => lines[index]!.replace(/\r$/, '');
72	  const blank = (index: number): boolean => text(index).trim() === '';
73	
74	  let lastContent = lines.length - 1;
75	  while (lastContent >= 0 && blank(lastContent)) lastContent -= 1;
76	  if (lastContent < 0) return whole;
77	
78	  // Trailing quote.
79	  let quoteLine = -1;
80	  if (QUOTE_LINE.test(text(lastContent))) {
81	    let runStart = lastContent;
82	    while (runStart > 0 && QUOTE_LINE.test(text(runStart - 1))) runStart -= 1;
83	    let before = runStart - 1;
84	    while (before >= 0 && blank(before)) before -= 1;
85	    if (before >= 0 && (ATTRIBUTION.test(text(before)) || ORIGINAL_MESSAGE.test(text(before)))) {
86	      quoteLine = before;
87	    } else if (before >= 1 && /wrote:$/i.test(text(before)) && !blank(before - 1)
88	      && ATTRIBUTION.test(`${text(before - 1)} ${text(before)}`)) {
89	      quoteLine = before - 1;
90	    } else if (lastContent - runStart + 1 >= 2) {
91	      quoteLine = runStart;
92	    }
93	  }
94	  const quoteStart = quoteLine >= 0 ? starts[quoteLine]! : bodyText.length;
95	  const regionEnd = quoteLine >= 0 ? quoteLine : lastContent + 1;
96	
97	  // Signature: the last delimiter before the quote with a short tail.
98	  let signatureStart = -1;
99	  for (let i = regionEnd - 1; i >= 0; i -= 1) {
100	    if (!SIGNATURE_DELIMITER.test(text(i))) continue;
101	    let tailEnd = regionEnd;
102	    while (tailEnd > i + 1 && blank(tailEnd - 1)) tailEnd -= 1;
103	    if (tailEnd - (i + 1) <= MAX_SIGNATURE_LINES) signatureStart = starts[i]!;
104	    break;
105	  }
106	
107	  const mainEnd = signatureStart >= 0 ? signatureStart : quoteStart;
108	  const main = bodyText.slice(0, mainEnd);
109	  if (main.trim() === '') return whole;
110	  return {
111	    main,
112	    signature: signatureStart >= 0 ? bodyText.slice(signatureStart, quoteStart) : null,
113	    quoted: quoteLine >= 0 ? bodyText.slice(quoteStart) : null,
114	  };
115	}
