1	<script setup lang="ts">
2	/**
3	 * Inline reply composer docked at the bottom of the open reader (Superhuman
4	 * reply shot). The thread stays visible above it; this pane only edits the
5	 * local plain-text draft through the shared `useDrafts` state wired by App.
6	 * The editor body is the shared DraftEditorCore; this surface supplies the
7	 * docked shell, the compact "Reply draft to {sender}" heading and the
8	 * read-only quoted context.
9	 *
10	 * Frozen draft contract (vertical-slice-04): the quoted latest message is a
11	 * READ-ONLY context block — it is never inserted into `bodyText`, which stays
12	 * blank on prepare. No Send/send-later/AI/attachments/rich text/Bcc/reply-all:
13	 * the footer offers "Save and close" and "Discard…" only. All text is rendered
14	 * through interpolation; no v-html. The fixed reply source is exposed to tests
15	 * and tools as data attributes only; opaque provider IDs are never shown.
16	 */
17	import type { DraftContent, DraftRef, DraftSource, MailError } from '../lib/ipc/client';
18	import DraftEditorCore from './DraftEditorCore.vue';
19	
20	const props = defineProps<{
21	  /** "Reply draft to {sender}" label: displayName ?? mailbox of the latest message. */
22	  recipientLabel: string;
23	  /** The latest message sender's mailbox: the default To. The recipient row shows the name only while To still equals it. */
24	  recipientMailbox?: string | null;
25	  /** Read-only quoted snippet of the latest message plain-text body. */
26	  quotedSnippet: string;
27	  activeRef: DraftRef | null;
28	  source: DraftSource | null;
29	  content: DraftContent;
30	  status: string;
31	  visible: boolean;
32	  creating: boolean;
33	  saving: boolean;
34	  conflict: boolean;
35	  error: MailError | null;
36	  createError: MailError | null;
37	  deleting: boolean;
38	  closing: boolean;
39	  transitioning: boolean;
40	  deletePending: boolean;
41	  confirmDiscard: boolean;
42	  discardBusy: boolean;
43	  confirmReload: boolean;
44	  copyPending: boolean;
45	  recoveryRequired: boolean;
46	  canCancelReplyPreparation: boolean;
47	  closeError: string | null;
48	}>();
49	
50	const emit = defineEmits<{
51	  closeEditor: [];
52	  setField: [field: keyof DraftContent, value: string];
53	  retry: [];
54	  askDiscard: [];
55	  confirmDiscard: [];
56	  cancelDiscard: [];
57	  askReload: [];
58	  confirmReload: [];
59	  cancelReload: [];
60	  saveAsNew: [];
61	  cancelReplyPreparation: [];
62	}>();
63	
64	function onSetField(field: keyof DraftContent, value: string): void {
65	  emit('setField', field, value);
66	}
67	</script>
68	
69	<template>
70	  <section class="reply-composer" aria-label="Inline reply draft composer" data-test="reply-composer">
71	    <section v-if="props.visible" class="composer" aria-label="Plain-text draft editor" data-test="composer">
72	      <DraftEditorCore
73	        autofocus="body"
74	        variant="reply"
75	        :recipient-label="props.recipientLabel"
76	        :recipient-mailbox="props.recipientMailbox ?? null"
77	        :active-ref="props.activeRef"
78	        :source="props.source"
79	        :content="props.content"
80	        :status="props.status"
81	        :creating="props.creating"
82	        :saving="props.saving"
83	        :conflict="props.conflict"
84	        :error="props.error"
85	        :create-error="props.createError"
86	        :deleting="props.deleting"
87	        :closing="props.closing"
88	        :transitioning="props.transitioning"
89	        :delete-pending="props.deletePending"
90	        :confirm-discard="props.confirmDiscard"
91	        :discard-busy="props.discardBusy"
92	        :confirm-reload="props.confirmReload"
93	        :copy-pending="props.copyPending"
94	        :recovery-required="props.recoveryRequired"
95	        :can-cancel-reply-preparation="props.canCancelReplyPreparation"
96	        :close-error="props.closeError"
97	        @close-editor="emit('closeEditor')"
98	        @set-field="onSetField"
99	        @retry="emit('retry')"
100	        @ask-discard="emit('askDiscard')"
101	        @confirm-discard="emit('confirmDiscard')"
102	        @cancel-discard="emit('cancelDiscard')"
103	        @ask-reload="emit('askReload')"
104	        @confirm-reload="emit('confirmReload')"
105	        @cancel-reload="emit('cancelReload')"
106	        @save-as-new="emit('saveAsNew')"
107	        @cancel-reply-preparation="emit('cancelReplyPreparation')"
108	      >
109	        <template #header>
110	          <header class="composer-heading">
111	            <h2>Reply draft <span class="reply-to">to <span data-test="draft-recipient-label">{{ props.recipientLabel }}</span></span></h2>
112	          </header>
113	        </template>
114	        <template #context>
115	          <!-- The fixed reply source: attributes only, never visible text. -->
116	          <span
117	            v-if="props.source?.kind === 'reply'"
118	            hidden
119	            data-test="reply-source"
120	            :data-source-conversation="props.source.conversation.conversationId"
121	            :data-source-message="props.source.sourceMessageId"
122	          ></span>
123	          <!-- Read-only quoted context of the latest message. It is display-only:
124	               it is never part of bodyText and the saved reply body stays blank. -->
125	          <blockquote class="reply-quoted" data-test="reply-quoted-context" aria-label="Quoted latest message (read-only)">{{ props.quotedSnippet }}</blockquote>
126	        </template>
127	      </DraftEditorCore>
128	    </section>
129	  </section>
130	</template>
