132	<style scoped>
133	/* Docked reply composer on the raised surface. Full 1px border, no accent
134	   side stripe. The shell scrolls only when the thread and composer genuinely
135	   do not fit; the body textarea, not the header stack, takes the space. */
136	.reply-composer {
137	  flex: 0 0 auto;
138	  min-height: 0;
139	  margin-top: 0.5rem;
140	  border: 1px solid var(--divider);
141	  border-radius: 6px;
142	  background: var(--surface-raised);
143	  color: var(--text-primary);
144	  font-size: var(--type-body);
145	  overflow-y: auto;
146	  max-height: 60%;
147	}
148	
149	.composer {
150	  min-width: 0;
151	  padding: 0.4rem 0.6rem;
152	  display: flex;
153	  flex-direction: column;
154	  gap: 0.2rem;
155	}
156	
157	.reply-to {
158	  color: var(--text-secondary);
159	  font-weight: var(--weight-regular);
160	  overflow-wrap: anywhere;
161	}
162	
163	/* Read-only quoted context: plain text only, never editable, never part of
164	   the draft body. UI face at the body size, clamped to three lines so it can
165	   never push the body down; the full snippet stays in the DOM text. */
166	.reply-quoted {
167	  margin: 0.3rem 0;
168	  padding: 0.1rem 0.5rem;
169	  border-left: 2px solid var(--rule);
170	  color: var(--text-secondary);
171	  font-family: var(--font-ui);
172	  font-size: var(--type-body);
173	  line-height: var(--leading-ui);
174	  white-space: pre-wrap;
175	  overflow-wrap: anywhere;
176	  user-select: text;
177	  display: -webkit-box;
178	  -webkit-box-orient: vertical;
179	  -webkit-line-clamp: 3;
180	  line-clamp: 3;
181	  overflow: hidden;
182	}
183	</style>
