1	/** Largest attachment the client will fetch: 5 MiB, shown to people as "5 MB". */
2	export const ATTACHMENT_LIMIT_BYTES = 5 * 1024 * 1024;
3	
4	const UNITS = ['KB', 'MB', 'GB'] as const;
5	
6	/**
7	 * Human file size in the style mail clients use: binary steps (1024) with the
8	 * short unit names. Bytes are exact ("27 B"); larger sizes keep one decimal
9	 * ("1.0 KB", "4.6 MB"). A negative size reads as 0 B; a size that is not a
10	 * finite number reads "unknown size" instead of inventing a value.
11	 */
12	export function formatBytes(bytes: number): string {
13	  if (!Number.isFinite(bytes)) return 'unknown size';
14	  const size = Math.max(0, Math.floor(bytes));
15	  if (size < 1024) return `${size} B`;
16	  let value = size / 1024;
17	  let unit = 0;
18	  // Rounding must not print "1024.0 KB": step up when the display would reach 1024.
19	  while (unit < UNITS.length - 1 && Math.round(value * 10) / 10 >= 1024) {
20	    value /= 1024;
21	    unit += 1;
22	  }
23	  return `${value.toFixed(1)} ${UNITS[unit]}`;
24	}
