1	import { onBeforeUnmount, ref } from 'vue';
2	import type { ConversationRef, MailClient } from '../lib/ipc/client';
3	import type { AttachmentDescriptor } from '../lib/ipc/generated';
4	
5	/** Stable identity of one file inside a conversation. */
6	export function attachmentKey(file: Pick<AttachmentDescriptor, 'messageId' | 'attachmentId'>): string {
7	  return `${file.messageId}:${file.attachmentId}`;
8	}
9	
10	export const ATTACHMENT_SAVE_ERROR = 'File not saved: unavailable offline, missing, cancelled, too large, or invalid content. Retry explicitly; a lost response may have left a unique file in Downloads.';
11	export const ATTACHMENT_CANCEL_ERROR = 'Could not confirm cancellation. A completed download may remain in Downloads.';
12	
13	/**
14	 * The one save/cancel transfer state shared by the Cmd+O chooser and the inline
15	 * attachment rows. One transfer at a time. Status and error text is exact and
16	 * honest: nothing is claimed saved until `saveAttachment` resolves, and a
17	 * cancellation is only "requested" until the transfer stops.
18	 *
19	 * Call from a component's setup: an in-flight transfer is cancelled and later
20	 * results are ignored when that component unmounts.
21	 */
22	export function useAttachmentTransfer(options: {
23	  client: () => MailClient;
24	  conversation: () => ConversationRef;
25	  preview: () => boolean;
26	}) {
27	  const pending = ref<string | null>(null);
28	  const status = ref('');
29	  const error = ref('');
30	  /** Key of the file the current status/error line belongs to. */
31	  const target = ref<string | null>(null);
32	  let live = true;
33	  let epoch = 0;
34	
35	  async function save(file: AttachmentDescriptor): Promise<void> {
36	    if (pending.value) return;
37	    const id = crypto.randomUUID();
38	    const mine = epoch;
39	    pending.value = id;
40	    error.value = '';
41	    status.value = '';
42	    target.value = attachmentKey(file);
43	    const client = options.client();
44	    try {
45	      const saved = await client.saveAttachment({
46	        conversation: { ...options.conversation() },
47	        messageId: file.messageId,
48	        attachmentId: file.attachmentId,
49	        requestId: id,
50	      });
51	      if (live && mine === epoch) {
52	        status.value = options.preview()
53	          ? 'Modelled save in preview memory only; no file was written.'
54	          : `Saved to Downloads as ${saved.filename}. No file was opened.`;
55	      }
56	    } catch {
57	      if (live && mine === epoch) error.value = ATTACHMENT_SAVE_ERROR;
58	    } finally {
59	      if (live && pending.value === id) pending.value = null;
60	    }
61	  }
62	
63	  async function cancel(): Promise<void> {
64	    const id = pending.value;
65	    if (!id) return;
66	    const mine = epoch;
67	    try {
68	      await options.client().cancelAttachment(id);
69	      if (live && mine === epoch) status.value = 'Cancellation requested; waiting for transfer to stop.';
70	    } catch {
71	      if (live && mine === epoch) error.value = ATTACHMENT_CANCEL_ERROR;
72	    }
73	  }
74	
75	  /** Drop the visible outcome (the conversation changed). Does not cancel. */
76	  function reset(): void {
77	    epoch += 1;
78	    status.value = '';
79	    error.value = '';
80	    target.value = null;
81	  }
82	
83	  onBeforeUnmount(() => {
84	    live = false;
85	    if (pending.value) void options.client().cancelAttachment(pending.value).catch(() => {});
86	  });
87	
88	  return { pending, status, error, target, save, cancel, reset };
89	}
